import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, readFileSync, readdirSync, appendFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-inv-g3-2/bot.mjs';
const base = mkdtempSync(path.join(tmpdir(), 'bot-'));
const stateDir = path.join(base, 'does', 'not', 'exist-yet'); // must be created by the bot
process.env.STATE_DIR = stateDir;
const bot = await import(BOT);
const { unsubscribe, resubscribe, mayEmail } = bot;
const now = new Date('2026-10-23T12:00:00Z');

test('new address: marketing blocked, receipt allowed, STATE_DIR created lazily', async () => {
  assert.equal(existsSync(stateDir), false);
  const m = await mayEmail('new@example.com', 'marketing', now);
  assert.equal(m.allowed, false);
  assert.match(m.reason, /No marketing opt-in/);
  const r = await mayEmail('new@example.com', 'receipt', now);
  assert.equal(r.allowed, true);
});

test('resubscribe opts in; normalization of case and spaces', async () => {
  await resubscribe('  Jane.Doe@Example.COM ');
  assert.equal((await mayEmail('jane.doe@example.com', 'marketing', now)).allowed, true);
  assert.equal((await mayEmail('\tJANE.DOE@example.com', 'marketing', now)).allowed, true);
});

test('unsubscribe blocks marketing only; receipts still go', async () => {
  await unsubscribe('jane.doe@example.com');
  const m = await mayEmail('Jane.Doe@Example.com', 'marketing', now);
  assert.equal(m.allowed, false);
  assert.match(m.reason, /unsubscribed/);
  assert.equal((await mayEmail('jane.doe@example.com', 'receipt', now)).allowed, true);
});

test('unsubscribe is idempotent (no file growth)', async () => {
  const file = path.join(stateDir, 'consent', readdirSync(path.join(stateDir, 'consent'))[0]);
  const before = readFileSync(file, 'utf8');
  await unsubscribe('jane.doe@example.com');
  await unsubscribe('jane.doe@example.com');
  assert.equal(readFileSync(file, 'utf8'), before);
});

test('resubscribe after unsubscribe re-enables marketing; later unsubscribe re-blocks', async () => {
  await resubscribe('jane.doe@example.com');
  assert.equal((await mayEmail('jane.doe@example.com', 'marketing', now)).allowed, true);
  await unsubscribe('jane.doe@example.com');
  assert.equal((await mayEmail('jane.doe@example.com', 'marketing', now)).allowed, false);
});

test('torn trailing line from a crashed worker is ignored and does not corrupt the next record', async () => {
  await resubscribe('torn@example.com');
  const file = path.join(stateDir, 'consent', readdirSync(path.join(stateDir, 'consent')).find(f => {
    return readFileSync(path.join(stateDir, 'consent', f), 'utf8').includes('torn@example.com');
  }));
  appendFileSync(file, '{"type":"unsubscr'); // crash mid-write, no newline
  assert.equal((await mayEmail('torn@example.com', 'marketing', now)).allowed, true);
  await unsubscribe('torn@example.com');
  assert.equal((await mayEmail('torn@example.com', 'marketing', now)).allowed, false);
});

test('invalid inputs', async () => {
  await assert.rejects(unsubscribe('   '), TypeError);
  await assert.rejects(resubscribe('no-at-sign'), TypeError);
  await assert.rejects(mayEmail('<EMAIL>', 'marketing', 'yesterday'), TypeError);
  const bad = await mayEmail('not-an-email', 'receipt', now);
  assert.equal(bad.allowed, false);
  const kind = await mayEmail('<EMAIL>', 'promo', now);
  assert.equal(kind.allowed, false);
  assert.match(kind.reason, /Unknown email kind/);
});

test('STATE_DIR unset throws', async () => {
  const saved = process.env.STATE_DIR;
  delete process.env.STATE_DIR;
  await assert.rejects(unsubscribe('<EMAIL>'), /STATE_DIR is not set/);
  process.env.STATE_DIR = saved;
});

function runWorker(code) {
  return new Promise((resolve, reject) => {
    const p = spawn(process.execPath, ['--input-type=module', '-e', code], {
      env: { ...process.env, STATE_DIR: stateDir }, stdio: ['ignore', 'inherit', 'inherit'],
    });
    p.on('exit', c => (c === 0 ? resolve() : reject(new Error('worker exit ' + c))));
  });
}

test('concurrent workers in separate processes record unsubscribes without loss or corruption', async () => {
  const target = 'race@example.com';
  await resubscribe(target);
  const N = 30;
  const jobs = [];
  for (let i = 0; i < N; i++) {
    // Half unsubscribe the shared address, half unsubscribe distinct addresses.
    const addr = i % 2 ? target : `bulk${i}@example.com`;
    jobs.push(runWorker(`const b = await import(${JSON.stringify(BOT)}); await b.unsubscribe(${JSON.stringify(' ' + addr.toUpperCase() + ' ')});`));
  }
  await Promise.all(jobs);
  // The shared address gets one line (idempotent check happens per process, so
  // a few duplicates are acceptable). Every line must be valid JSON.
  const file = path.join(stateDir, 'consent', readdirSync(path.join(stateDir, 'consent')).find(f =>
    readFileSync(path.join(stateDir, 'consent', f), 'utf8').includes(target)));
  const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
  assert.ok(lines.length >= 2);
  assert.equal((await mayEmail(target, 'marketing', now)).allowed, false);
  for (let i = 0; i < N; i += 2) {
    const addr = `bulk${i}@example.com`;
    assert.equal((await mayEmail(addr, 'marketing', now)).allowed, false, addr);
  }
});

test('a new process sees state written by earlier processes', async () => {
  await runWorker(`const b = await import(${JSON.stringify(BOT)}); await b.resubscribe('fresh@example.com');`);
  assert.equal((await mayEmail('fresh@example.com', 'marketing', now)).allowed, true);
});
EOF
cd /tmp/courier-bot-test && node --test test.mjs 2>&1 | tail -40
